contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(0));
        // Only the contract itself is msg.sender on c; owned() can only succeed if we are already owner.
        // Read that precondition via the public getter.
        require(c.owner() == address(this));
        require(address(this) == caller || true);
        c.owned();
        assert(c.owner() == address(this));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnValue) public payable {
        uint256 beforeSupply = c.totalSupply();
        bool reverted;
        try c.burn(burnValue) { reverted = false; } catch { reverted = true; }
        uint256 afterSupply = c.totalSupply();
        assert(reverted ? afterSupply == beforeSupply : afterSupply + burnValue == beforeSupply);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 value) public payable {
        require(true);

        address self = address(this);
        uint256 beforeSelf = c.balanceOf(self);
        uint256 beforeOwner = c.balanceOf(c.owner());
        uint256 beforeSupply = c.totalSupply();

        bool reverted;
        try c.burn(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterSelf = c.balanceOf(self);
            uint256 afterOwner = c.balanceOf(c.owner());
            uint256 afterSupply = c.totalSupply();

            uint256 unaffected;
            if (self == c.owner()) {
                unaffected = beforeSupply - afterSupply;
            } else {
                unaffected = beforeSelf - afterSelf;
            }

            assert(unaffected == 0 && afterOwner == beforeOwner);
        } else {
            assert(c.balanceOf(self) == beforeSelf);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 value, address other) public payable {
        require(other != address(0));
        require(other != address(this));

        address caller = address(this);
        uint256 beforeOther = c.balanceOf(other);
        uint256 beforeSelf = c.balanceOf(caller);
        uint256 beforeSupply = c.totalSupply();

        bool reverted;
        try c.burn(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterOther = c.balanceOf(other);
        uint256 afterSelf = c.balanceOf(caller);
        uint256 afterSupply = c.totalSupply();

        bool callerIsOther = (caller == other);

        assert(
            (reverted && afterOther == beforeOther && afterSelf == beforeSelf && afterSupply == beforeSupply) ||
            (!reverted && beforeSelf == value && afterSelf == 0 && afterSupply + value == beforeSupply && afterOther == beforeOther && !callerIsOther)
        );
    }

    receive() external payable {}
}

